#!/usr/bin/env python3
"""sun — attribute human and agent edits as git commits plus an operation log.

State lives in .git/sun/: events.jsonl holds one operation per line, each
pointing at a commit (several operations may point at the same commit), and
state.json tracks per-session turn counters. Wire it into Claude Code with
`sun install-hooks`; other harnesses can call `sun hook <event>` directly.
"""
import argparse
import json
import os
import subprocess
import sys
import time
import uuid

EDIT_TOOLS = "Edit|Write|MultiEdit|NotebookEdit"
HUMAN_HOOKS = ("SessionStart", "UserPromptSubmit", "PreToolUse")


def run(cmd, input=None, check=True):
    p = subprocess.run(cmd, input=input, capture_output=True, text=True)
    if check and p.returncode != 0:
        sys.exit("sun: `%s` failed:\n%s" % (" ".join(cmd), (p.stderr or p.stdout).strip()))
    return p


def git(*args, **kw):
    return run(["git"] + list(args), **kw)


def ensure_repo():
    p = git("rev-parse", "--show-toplevel", check=False)
    if p.returncode != 0:
        sys.exit("sun: not a git repository — run `sun init` first")
    os.chdir(p.stdout.strip())


def sun_dir():
    d = os.path.join(git("rev-parse", "--git-dir").stdout.strip(), "sun")
    os.makedirs(d, exist_ok=True)
    return d


def now():
    return time.strftime("%Y-%m-%dT%H:%M:%S")


def load_state():
    path = os.path.join(sun_dir(), "state.json")
    if os.path.exists(path):
        with open(path) as f:
            return json.load(f)
    return {"sessions": {}}


def save_state(state):
    with open(os.path.join(sun_dir(), "state.json"), "w") as f:
        json.dump(state, f, indent=2)


def load_events():
    path = os.path.join(sun_dir(), "events.jsonl")
    if not os.path.exists(path):
        return []
    with open(path) as f:
        return [json.loads(line) for line in f if line.strip()]


def append_event(event):
    with open(os.path.join(sun_dir(), "events.jsonl"), "a") as f:
        f.write(json.dumps(event) + "\n")


def events_by_commit():
    by = {}
    for ev in load_events():
        by.setdefault(ev["commit"], []).append(ev)
    return by


def human_actor():
    name = git("config", "user.name", check=False).stdout.strip() or os.environ.get("USER", "unknown")
    return "human:" + name.lower().replace(" ", "-")


def identity_args():
    if git("config", "user.email", check=False).stdout.strip():
        return []
    return ["-c", "user.name=sun", "-c", "user.email=sun@localhost"]


def capture(actor, kind="edit", session=None, turn=None, tool_calls=None, extra=None):
    """Commit any pending working-tree changes and record them as one operation."""
    if not git("status", "--porcelain").stdout.strip():
        return None
    git("add", "-A")
    edits = []
    for f in git("diff", "--cached", "--name-only").stdout.splitlines():
        edit = {"file": f, "patch": git("diff", "--cached", "--", f).stdout}
        for tc in tool_calls or []:
            tf = tc["input"].get("file") or ""
            if tf and (tf == f or tf.endswith("/" + f)):
                edit["tool_call_id"] = tc["id"]
                edit["attribution"] = {"method": "edit_tool"}
        edits.append(edit)
    msg = "sun: %s by %s" % (kind, actor) + (" (turn %d)" % turn if turn else "")
    git(*identity_args(), "commit", "-q", "-m", msg, "--author", "%s <sun@sun>" % actor)
    event = {
        "id": uuid.uuid4().hex[:8],
        "type": kind,
        "actor": actor,
        "timestamp": now(),
        "commit": git("rev-parse", "HEAD").stdout.strip(),
        "edits": edits,
    }
    if session:
        event["session"] = session
    if turn:
        event["turn"] = "turn%d" % turn
    if tool_calls:
        event["tool_calls"] = tool_calls
    event.update(extra or {})
    append_event(event)
    return event


def cmd_init(args):
    if git("rev-parse", "--git-dir", check=False).returncode != 0:
        run(["git", "init", "-q"])
    ensure_repo()
    save_state(load_state())
    if git("rev-parse", "HEAD", check=False).returncode != 0:
        git("add", "-A")
        git(*identity_args(), "commit", "-q", "--allow-empty", "-m", "sun: init")
    print("sun: initialized (state in .git/sun/)")


def cmd_hook(args):
    ensure_repo()
    payload = {}
    if not sys.stdin.isatty():
        raw = sys.stdin.read().strip()
        if raw:
            try:
                payload = json.loads(raw)
            except ValueError:
                payload = {}
    event = args.event or payload.get("hook_event_name", "Stop")
    session = payload.get("session_id", "unknown")
    state = load_state()
    sess = state["sessions"].setdefault(session, {"turn": 0})
    if event in HUMAN_HOOKS:
        # Anything dirty before the agent touches files belongs to the human.
        capture(human_actor())
        if event == "UserPromptSubmit":
            sess["turn"] += 1
    else:  # PostToolUse, Stop, SubagentStop, ...
        tool_calls = None
        if payload.get("tool_name"):
            tool_input = payload.get("tool_input") or {}
            tool_calls = [{
                "id": payload.get("tool_use_id") or "tool-" + uuid.uuid4().hex[:6],
                "tool": payload["tool_name"],
                "input": {"file": tool_input.get("file_path") or tool_input.get("notebook_path") or ""},
            }]
        sess["turn"] = sess["turn"] or 1
        capture("agent:claude/%s" % session, session=session,
                turn=sess["turn"], tool_calls=tool_calls)
    save_state(state)


def cmd_log(args):
    ensure_repo()
    by = events_by_commit()
    extra = ["-n", str(args.n)] if args.n else []
    out = git("log", "--date=short", "--pretty=%H\x1f%h\x1f%ad\x1f%s", *extra).stdout
    for line in out.splitlines():
        full, short, date, subject = line.split("\x1f")
        print("%s %s %s" % (short, date, subject))
        for ev in by.get(full, []):
            turn = " %s" % ev["turn"] if ev.get("turn") else ""
            print("         op %s: %s%s" % (ev["id"], ev["actor"], turn))


def cmd_show(args):
    ensure_repo()
    full = git("rev-parse", args.commit).stdout.strip()
    print(git("show", "-s", "--date=short", "--pretty=commit %h  %ad  %s", full).stdout.strip())
    events = events_by_commit().get(full, [])
    if not events:
        print("no sun operations recorded for this commit")
    for ev in events:
        head = "\nop %s  type=%s  actor=%s" % (ev["id"], ev["type"], ev["actor"])
        if ev.get("turn"):
            head += "  " + ev["turn"]
        print(head)
        for tc in ev.get("tool_calls", []):
            print("  tool_call %s: %s(%s)" % (tc["id"], tc["tool"], tc["input"].get("file", "")))
        for edit in ev["edits"]:
            print("  %s" % edit["file"])
            for pl in edit["patch"].splitlines():
                print("    " + pl)


def commit_edits(rev):
    if git("rev-parse", rev + "~1", check=False).returncode != 0:
        return []
    edits = []
    for f in git("diff", rev + "~1", rev, "--name-only").stdout.splitlines():
        edits.append({"file": f, "patch": git("diff", rev + "~1", rev, "--", f).stdout})
    return edits


def cmd_undo(args):
    ensure_repo()
    actor = human_actor()
    if args.commit is not None:
        full = git("rev-parse", args.commit).stdout.strip()
        git(*identity_args(), "revert", "--no-edit", full)
        head = git("rev-parse", "HEAD").stdout.strip()
        append_event({"id": uuid.uuid4().hex[:8], "type": "undo", "actor": actor,
                      "timestamp": now(), "commit": head,
                      "undoes": {"commit": full}, "edits": commit_edits(head)})
        print("sun: reverted commit %s" % full[:8])
    else:
        events = [e for e in load_events() if e["type"] == "edit"]
        if not events:
            sys.exit("sun: no operations to undo")
        if args.op in (None, "latest"):
            ev = events[-1]
        else:
            match = [e for e in events if e["id"] == args.op]
            if not match:
                sys.exit("sun: no operation %s" % args.op)
            ev = match[0]
        for edit in ev["edits"]:
            run(["git", "apply", "-R", "--whitespace=nowarn"], input=edit["patch"])
        done = capture(actor, kind="undo", extra={"undoes": {"op": ev["id"]}})
        print("sun: undid op %s (commit %s)" % (ev["id"], done["commit"][:8]))


def cmd_install_hooks(args):
    ensure_repo()
    path = os.path.join(".claude", "settings.json")
    settings = {}
    if os.path.exists(path):
        with open(path) as f:
            settings = json.load(f)
    hooks = settings.setdefault("hooks", {})

    def add(name, matcher=None):
        entries = hooks.setdefault(name, [])
        if any("sun hook" in json.dumps(e) for e in entries):
            return
        entry = {"hooks": [{"type": "command", "command": "sun hook"}]}
        if matcher:
            entry["matcher"] = matcher
        entries.append(entry)

    add("SessionStart")
    add("UserPromptSubmit")
    add("PreToolUse", EDIT_TOOLS)
    add("PostToolUse", EDIT_TOOLS)
    add("Stop")
    os.makedirs(".claude", exist_ok=True)
    with open(path, "w") as f:
        json.dump(settings, f, indent=2)
    print("sun: hooks written to %s" % path)


def cmd_viz(args):
    ensure_repo()
    out = git("log", "--all", "--topo-order", "--date=short",
              "--pretty=%H\x1f%h\x1f%an\x1f%ad\x1f%s\x1f%D\x1e").stdout
    commits = []
    for rec in out.replace("\n", "").split("\x1e"):
        if not rec.strip():
            continue
        full, short, author, date, subject, refs = rec.split("\x1f")
        commits.append({"hash": full, "short": short, "author": author, "date": date,
                        "subject": subject,
                        "refs": [r.strip() for r in refs.split(",") if r.strip()]})
    data = {"commits": commits, "events": load_events()}
    html = TEMPLATE.replace("__DATA__", json.dumps(data).replace("</", "<\\/"))
    with open(args.output, "w") as f:
        f.write(html)
    print("sun: wrote %s (%d commits, %d operations)" % (args.output, len(commits), len(data["events"])))


TEMPLATE = """<!doctype html>
