def main():
    ap = argparse.ArgumentParser(prog="sun", description=__doc__)
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("init", help="init git repo and .git/sun state")
    p = sub.add_parser("hook", help="called from agent harness hooks (reads JSON on stdin)")
    p.add_argument("event", nargs="?", help="hook event name if not in the stdin payload")
    p = sub.add_parser("log", help="git log with operations attached to each commit")
    p.add_argument("-n", type=int, help="max commits to show")
    p = sub.add_parser("show", help="show operations for a specific commit")
    p.add_argument("commit")
    p = sub.add_parser("undo", help="undo one operation or one commit")
    p.add_argument("--op", nargs="?", const="latest", help="operation id (default: latest)")
    p.add_argument("--commit", nargs="?", const="HEAD", help="commit hash (default: HEAD)")
    p = sub.add_parser("viz", help="write a self-contained HTML visualization")
    p.add_argument("-o", "--output", default="sun-viz.html")
    sub.add_parser("install-hooks", help="wire sun into .claude/settings.json")
    args = ap.parse_args()
    {"init": cmd_init, "hook": cmd_hook, "log": cmd_log, "show": cmd_show,
     "undo": cmd_undo, "viz": cmd_viz, "install-hooks": cmd_install_hooks}[args.cmd](args)


if __name__ == "__main__":
    main()

